Definition undefined_ExceptionKind '(tt : unit) : M (ExceptionKind) :=
   (internal_pick
      ([StackUnderflow;
      StackOverflow;
      OutOfGas;
      InvalidOpcode;
      InvalidJump;
      StaticViolation;
      CallDepthExceeded;
      InsufficientBalance;
      WriteProtection;
      InitCodeTooLarge;
      NonceOverflow;
