Definition ecrecover_addr (h : vec (mword 8) 32) (yparity : y_parity) (r : word) (s : word)
(*(0 <=? yparity) && (yparity <=? 1)*) (*(0 <=? r) && (r <=? (2 ^ 256 - 1))*)
(*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M ((bool * address_typ)) :=
   let yparity := (yparity).(y_parity_value) in
   let r := (r).(word_value) in
   let s := (s).(word_value) in
   (host_ecrecover (h) (Build_y_parity ((yparity))) (Build_word ((r))) (Build_word ((s)))) >>= fun recovered =>
   returnM ((recovered.(AddressResult_success), recovered.(AddressResult_address))).

