Definition receipt_fields
(_limit : Z) (_regular_limit : Z) (tx_type : TxType) (success : bool) (gas_used : Z)
(execution_gas : Z) (state_gas : Z) (logs : LogSeriesRef)
(*(0 <=? _limit) &&
  ((_limit <=? (2 ^ 64 - 1)) &&
    ((0 <=? _regular_limit) &&
      ((_regular_limit <=? _limit) &&
        ((0 <=? gas_used) &&
          ((gas_used <=? _limit) &&
            ((0 <=? execution_gas) &&
              ((execution_gas <=? _regular_limit) &&
                ((0 <=? state_gas) &&
                  ((state_gas <=? _limit) && (gas_used <=? (execution_gas + state_gas)))))))))))*)
: ReceiptFields _limit _regular_limit gas_used execution_gas state_gas :=
   {| ReceiptFields_tx_type := tx_type;
      ReceiptFields_success := success;
      ReceiptFields_gas_used := gas_used;
      ReceiptFields_execution_gas := execution_gas;
      ReceiptFields_state_gas := state_gas;
      ReceiptFields_logs := logs |}.

Definition receipt_within
(limit : Z) (regular_limit : Z) (tx_type : TxType) (success : bool) (gas_used : Z)
(execution_gas : Z) (state_gas : Z) (logs : LogSeriesRef)
(*(0 <=? limit) &&
  ((limit <=? (2 ^ 64 - 1)) &&
    ((0 <=? regular_limit) &&
      ((regular_limit <=? limit) &&
        ((0 <=? gas_used) &&
          ((gas_used <=? limit) &&
            ((0 <=? execution_gas) &&
              ((execution_gas <=? regular_limit) &&
                ((0 <=? state_gas) &&
                  ((state_gas <=? limit) && (gas_used <=? (execution_gas + state_gas)))))))))))*)
: ReceiptWithin limit regular_limit :=
   @existT _ _ gas_used (@existT _ _ execution_gas (@existT _ _ state_gas ((receipt_fields (limit)
                                                                              (regular_limit)
                                                                              (tx_type) (success)
                                                                              (gas_used)
                                                                              (execution_gas)
                                                                              (state_gas) (logs) : ReceiptFields limit regular_limit gas_used execution_gas state_gas)))).

