   let out : vec (mword 8) 256 := EMPTY_LOGS_BLOOM in
   (let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := 255 in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 out
     (fun i '(out) =>
       (stateless_input_slice_byte (reference) (i)) >>= fun (w__0 : mword 8) =>
       let out := (vec_update_dec (out) ((Z.sub (255) (i))) (w__0))  : vec (mword 8) 256 in
       returnM (out))))
    : M (vec (mword 8) 256).

Definition logs_bloom_matches_ref {ex299251_ : Z}
(computed : vec (mword 8) 256) (reference : StatelessInputSliceFields ex299251_ 256)
(ex299252_ := 256)
(*(0 <=? ex299251_) && ((0 <=? ex299252_) && ((ex299251_ + ex299252_) <=? (2 ^ 32 - 1))) &&
  (ex299252_ =? 256)*)
: M (bool) :=
   (logs_bloom_from_ref
      (autocast (T := fun _sz => (StatelessInputSliceFields _ _sz)%type)
      (reference))) >>= fun expected =>
   returnM ((logs_bloom_equal (computed) (expected))).

