(*(0 <=? ex299709_) && ((0 <=? ex299710_) && ((ex299709_ + ex299710_) <=? (2 ^ 32 - 1))) &&
  ((0 <=? ex299710_) && ((ex299710_ + 32) <=? (2 ^ 32 - 1)))*) (*(0 <=? fork) && (fork <=? 16)*)
