: M (unit) :=
   let fork := (fork).(Fork_value) in
   let table := (table).(jump_table_index_value) in
   let code_len := code.(CodeRegionSliceFields_len) in
   let scanning : bool := true in
   let position : Z := pc in
   (whileMT
     (position, scanning)
     (fun '(position, scanning) => Z.sub ex299710_ (position))
     (fun '(position, scanning) =>
       returnM ((andb (scanning) (((Z.ltb (position) ex299710_)  : bool)))))
     (fun '(position, scanning) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        let current := position in
        (code_slice_byte (code) (current)) >>= fun opcode =>
        (if eq_vec (opcode) ((Ox"5B")) return M (unit) then
           (jumpdest_table_mark (Build_jump_table_index ((table))) (Build_code_length (ex299710_))
              (Build_code_pointer ((current)))) >>= fun marked =>
           (assert_exp marked "JUMPDEST mark")
            : M (unit)
         else returnM (tt)) >>
        let opcode_value := uint (opcode) in
        (if andb ((Z.leb (96) (opcode_value))) ((Z.leb (opcode_value) (127))) then
           returnM ((Z.sub (opcode_value) (94)))
         else if Z.geb (fork) (Amsterdam) return M (Z) then
           let operation := deep_stack_operation (Build_opcode ((opcode_value))) in
           (code_slice_byte (code) ((Z.add (current) (1)))) >>= fun immediate =>
           let immediate_valid := deep_stack_operation_immediate_valid (operation) (immediate) in
           returnM ((if immediate_valid then 2 else 1))
         else returnM (1)) >>= fun (step : Z) =>
        let '((position, scanning)) :=
          (if Z.ltb (step) ((Z.sub ex299710_ (current))) then
             let position : Z := Z.add (current) (step) in
             (position, scanning)
           else
             let scanning : bool := false in
             (position, scanning))
           : (Z * bool) in
        returnM ((position, scanning)))
        : M ((Z * bool)))) >>= fun '((position, scanning)
   : (Z * bool)) =>
   returnM (tt).

