Definition output_buffer_slice (len : Z) (*(0 <=? len) && (len <=? (2 ^ 32 - 1))*) : OutputSlice :=
   if Z.eqb (len) (0) then
     @existT _ _ 0 (@existT _ _ 0 ((EMPTY_OUTPUT_SLICE : OutputSliceFields 0 0)))
   else @existT _ _ len (@existT _ _ 0 ((output_slice (0) (len) : OutputSliceFields 0 len))).

Definition freeze_memory_output {ex301064_ : Z} {ex301063_ : Z}
(data : EvmMemorySliceFields ex301063_ ex301064_)
(*(0 <=? ex301063_) && ((0 <=? ex301064_) && ((ex301063_ + ex301064_) <=? (2 ^ 32 - 1)))*)
: M (OutputSlice) :=
   let len := data.(EvmMemorySliceFields_len) in
   (if Z.eqb (len) (0) then
      returnM ((@existT _ _ 0 (@existT _ _ 0 ((EMPTY_OUTPUT_SLICE : OutputSliceFields 0 0)))) : {len & {off & (OutputSliceFields off len)}}%type)
    else
      (output_buffer_store_memory
         (@existT _ _ ex301064_ (@existT _ _ ex301063_ ((data : EvmMemorySliceFields ex301063_ ex301064_))))) >>= fun stored =>
      returnM ((if stored then output_buffer_slice (len)
                else @existT _ _ 0 (@existT _ _ 0 ((EMPTY_OUTPUT_SLICE : OutputSliceFields 0 0)))) : {len & {off & (OutputSliceFields off len)}}%type))
    : M ({len & {off & (OutputSliceFields off len)}}%type).

Definition freeze_input_output {ex301068_ : Z} {ex301067_ : Z}
(data : StatelessInputSliceFields ex301067_ ex301068_)
(*(0 <=? ex301067_) && ((0 <=? ex301068_) && ((ex301067_ + ex301068_) <=? (2 ^ 32 - 1)))*)
: M (OutputSlice) :=
   let len := data.(StatelessInputSliceFields_len) in
   (if Z.eqb (len) (0) then
      returnM ((@existT _ _ 0 (@existT _ _ 0 ((EMPTY_OUTPUT_SLICE : OutputSliceFields 0 0)))) : {len & {off & (OutputSliceFields off len)}}%type)
    else
      (output_buffer_store_input
         (@existT _ _ ex301068_ (@existT _ _ ex301067_ ((data : StatelessInputSliceFields ex301067_ ex301068_))))) >>= fun stored =>
      returnM ((if stored then output_buffer_slice (len)
                else @existT _ _ 0 (@existT _ _ 0 ((EMPTY_OUTPUT_SLICE : OutputSliceFields 0 0)))) : {len & {off & (OutputSliceFields off len)}}%type))
    : M ({len & {off & (OutputSliceFields off len)}}%type).

Definition freeze_calldata_output (data : CalldataSlice) : M (OutputSlice) :=
   match data with
   | InputCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (freeze_input_output (bytes))  : M ({len & {off & (OutputSliceFields off len)}}%type)
   | MemoryCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (freeze_memory_output (bytes))  : M ({len & {off & (OutputSliceFields off len)}}%type)
   end
    : M ({len & {off & (OutputSliceFields off len)}}%type).

Definition output_buffer_word (value : word) (*(0 <=? value) && (value <=? (2 ^ 256 - 1))*)
: M (OutputSlice) :=
   let value := (value).(word_value) in
   (output_buffer_store_word (Build_word ((value)))) >>= fun stored =>
   returnM ((if stored then output_buffer_slice (WORD_BYTE_LENGTH)
             else @existT _ _ 0 (@existT _ _ 0 ((EMPTY_OUTPUT_SLICE : OutputSliceFields 0 0)))) : {len & {off & (OutputSliceFields off len)}}%type).

Definition output_buffer_words (first : word) (second : word)
(*(0 <=? first) && (first <=? (2 ^ 256 - 1))*) (*(0 <=? second) && (second <=? (2 ^ 256 - 1))*)
: M (OutputSlice) :=
   let first := (first).(word_value) in
   let second := (second).(word_value) in
   (output_buffer_store_words (Build_word ((first))) (Build_word ((second)))) >>= fun stored =>
   returnM ((if stored then output_buffer_slice (DOUBLE_WORD_BYTE_LENGTH)
             else @existT _ _ 0 (@existT _ _ 0 ((EMPTY_OUTPUT_SLICE : OutputSliceFields 0 0)))) : {len & {off & (OutputSliceFields off len)}}%type).

Definition undefined_EnvField '(tt : unit) : M (EnvField) :=
   (internal_pick
      ([F_Number;
      F_Timestamp;
      F_Coinbase;
      F_BaseFee;
      F_ChainId;
      F_GasLimit;
      F_PrevRandao;
      F_Origin;
      F_GasPrice;
      F_SlotNumber]))
    : M (EnvField).

Definition k_env (f : EnvField) : M (word) :=
   (read_reg k_tx >>= fun '(@existT _ _ __active_tx active_tx) =>
   match f with
   | F_Number =>
      read_reg k_header >>= fun (w__0 : BlockHeader) =>
      let number :=
        (word_of_block_number
           (Build_block_number (((w__0.(BlockHeader_number)).(block_number_value))))).(block_number_value) in
      returnM (((u256 (number)).(word_value)))
   | F_Timestamp =>
      read_reg k_header >>= fun (w__1 : BlockHeader) =>
      let timestamp :=
        (word_of_block_timestamp
           (Build_block_timestamp (((w__1.(BlockHeader_timestamp)).(block_timestamp_value))))).(block_timestamp_value) in
      returnM (((u256 (timestamp)).(word_value)))
   | F_Coinbase =>
      read_reg k_header >>= fun (w__2 : BlockHeader) =>
      returnM (((address_to_word (w__2.(BlockHeader_fee_recipient))).(word_value)))
   | F_BaseFee =>
      read_reg k_header >>= fun (w__3 : BlockHeader) =>
      returnM ((w__3.(BlockHeader_base_fee)).(word_value))
   | F_ChainId =>
      (read_reg k_chain_id) >>= fun semanticResult =>
      returnM (semanticResult).(chain_identifier_value) >>= fun (w__4 : Z) =>
      let chain_id :=
        (word_of_chain_identifier (Build_chain_identifier ((w__4)))).(chain_identifier_value) in
      returnM (((u256 (chain_id)).(word_value)))
   | F_GasLimit =>
      read_reg k_header >>= fun (w__5 : BlockHeader) =>
      returnM (((u256 ((w__5.(BlockHeader_gas_limit)).(block_gas_limit_value))).(word_value)))
   | F_PrevRandao =>
      read_reg k_header >>= fun (w__6 : BlockHeader) =>
      returnM ((w__6.(BlockHeader_prev_randao)).(word_value))
   | F_Origin => returnM (((address_to_word (active_tx.(TxEnvFields_origin))).(word_value)))
   | F_GasPrice => returnM ((active_tx.(TxEnvFields_gas_price)).(word_value))
   | F_SlotNumber =>
      read_reg k_header >>= fun (w__7 : BlockHeader) =>
      let slot_number :=
        (word_of_slot_number
           (Build_slot_number_typ (((w__7.(BlockHeader_slot_number)).(slot_number_value))))).(slot_number_value) in
      returnM (((u256 (slot_number)).(word_value)))
   end
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition k_coinbase '(tt : unit) : M (address_typ) :=
   read_reg k_header >>= fun (w__0 : BlockHeader) => returnM (w__0.(BlockHeader_fee_recipient)).

Definition blockhash_word_distance (current : Z) (number : Z)
(*(0 <=? number) && ((number <? current) && (current <? (2 ^ 256)))*)
: Z :=
   Z.sub (current) (number).

Definition k_blockhash (number_word : word)
(*(0 <=? number_word) && (number_word <=? (2 ^ 256 - 1))*)
: M (hash) :=
   let number_word := (number_word).(word_value) in
   read_reg k_header >>= fun (w__0 : BlockHeader) =>
   let current := (w__0.(BlockHeader_number)).(block_number_value) in
   let current_number :=
     (word_of_block_number (Build_block_number ((current)))).(block_number_value) in
   let current_word : Z := (u256 (current_number)).(word_value) in
   (if Z.ltb (number_word) (current_word) return M (vec (mword 8) 32) then
      let distance_word := blockhash_word_distance (current_word) (number_word) in
      (if Z.leb (distance_word) (256) return M (vec (mword 8) 32) then
         let distance : Z := distance_word in
         (read_reg k_n_headers) >>= fun semanticResult =>
         returnM (semanticResult).(ancestor_hash_count_value) >>= fun (w__1 : Z) =>
         (if Z.ltb (w__1) (distance) return M (vec (mword 8) 32) then
            (fatal_error (WitnessDeficient))
             : M (vec (mword 8) 32)
          else
            let index : Z := Z.sub (distance) (1) in
            (ancestor_hash_read (Build_ancestor_index ((index))))
             : M (vec (mword 8) 32))
          : M (vec (mword 8) 32)
       else returnM (ZERO_HASH))
       : M (vec (mword 8) 32)
    else returnM (ZERO_HASH))
    : M (vec (mword 8) 32).

Definition k_blobhash (index_word : word) (*(0 <=? index_word) && (index_word <=? (2 ^ 256 - 1))*)
: M (word) :=
   let index_word := (index_word).(word_value) in
   (read_reg k_tx >>= fun '(@existT _ _ __active_tx active_tx) =>
   let count := active_tx.(TxEnvFields_blob_hashes).(BlobHashesFields_count) in
   (if Z.ltb (index_word) (count) return M (Z) then
      let index := index_word in
      let offset : Z := Z.add ((Z.mul (33) (index))) (1) in
      ((stateless_input_slice_load_n
          (projT2 (projT2 (active_tx.(TxEnvFields_blob_hashes).(BlobHashesFields_bytes)))) (offset)
          (WORD_BYTE_LENGTH)) >>= fun semanticResult =>
       returnM (semanticResult).(word_value))
       : M (Z)
    else returnM ((ZERO_WORD).(word_value)))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition k_create_addr (a : vec (mword 8) 20) (nonce : account_nonce)
(*(0 <=? nonce) && (nonce <=? (2 ^ 64 - 1))*)
: M (address_typ) :=
   let nonce := (nonce).(account_nonce_value) in
   (create_address (a) (Build_account_nonce ((nonce))))
    : M (vec (mword 8) 20).

Definition k_create2_addr (a : vec (mword 8) 20) (salt : word) (inithash : vec (mword 8) 32)
(*(0 <=? salt) && (salt <=? (2 ^ 256 - 1))*)
: M (address_typ) :=
   let salt := (salt).(word_value) in
   (create2_address (a) (Build_word ((salt))) (inithash))
    : M (vec (mword 8) 20).

Axiom stateless_storage_by_key : forall  (_ : hash) (_ : hash) , word.

Axiom precompile_id_for_address : forall  (_ : address_typ) , precompile_id.

Definition storage_key (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: StorageKey :=
   let s := (s).(word_value) in {| StorageKey_addr := a;  StorageKey_slot := (Build_word (s)) |}.

Definition k_account_is_warm (a : vec (mword 8) 20) : M (bool) :=
   let precompile_id := precompile_id_for_address (a) in
   (if generic_neq (precompile_id) (NotPrecompile) then returnM (true)
    else (account_is_warm (a))  : M (bool))
    : M (bool).

Definition k_account_mark_warm (a : vec (mword 8) 20) : M (unit) :=
   let precompile_id := precompile_id_for_address (a) in
   (if generic_neq (precompile_id) (NotPrecompile) then returnM (tt)
    else (account_mark_warm (a))  : M (unit))
    : M (unit).

Definition k_slot_is_warm (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (bool) :=
   let s := (s).(word_value) in (storage_is_warm (a) (Build_word ((s))))  : M (bool).

Definition k_slot_mark_warm (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let s := (s).(word_value) in (storage_mark_warm (a) (Build_word ((s))))  : M (unit).

Definition k_prewarm_slot (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let s := (s).(word_value) in (storage_mark_warm (a) (Build_word ((s))))  : M (unit).

Axiom stateless_account_by_key : forall  (_ : hash) (_ : hash) , Account.

Definition k_aload (a : vec (mword 8) 20) : M (Account) :=
   (acct_tx_get (a)) >>= fun tx_account =>
   (if tx_account.(AccountRow_found) then returnM (tx_account.(AccountRow_account))
    else
      (bal_account_touch (a)) >>
      (acct_block_get (a)) >>= fun block_account =>
      (if block_account.(AccountRow_found) then returnM (block_account.(AccountRow_account))
       else
         (keccak256_address (a)) >>= fun address_hash =>
         read_reg k_parent_state_root >>= fun (w__0 : vec (mword 8) 32) =>
         let account := stateless_account_by_key (w__0) (address_hash) in
         (acct_block_cache (a) (address_hash) (account)) >> returnM (account))
       : M (Account))
    : M (Account).

Definition k_sload (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (StorageValue) :=
   let s := (s).(word_value) in
   catch_early_return
     (let key := storage_key (a) (Build_word ((s))) in
     liftR ((storage_tx_get (key))) >>= fun tx_value =>
     match tx_value with
     | StorageTxHit value =>
        (early_return (value  : StorageValue) : MR StorageValue unit)  : MR (StorageValue) (unit)
     | StorageTxCleared _ =>
        liftR ((bal_storage_read (a) (Build_word ((s))))) >>
        (early_return (({| StorageValue_curr := (Build_word ((ZERO_WORD).(word_value)));
                           StorageValue_orig := (Build_word ((ZERO_WORD).(word_value))) |})
         : StorageValue) :
          MR StorageValue unit)
         : MR (StorageValue) (unit)
     | StorageTxMiss _ =>
        liftR ((bal_storage_read (a) (Build_word ((s)))))  : MR (StorageValue) (unit)
     end >>
     liftR ((storage_block_get (key))) >>= fun block_value =>
     (if block_value.(StorageBlockRow_found) then
        returnR (StorageValue) (({| StorageValue_curr :=
                                      (Build_word ((block_value.(StorageBlockRow_value).(StorageValue_curr)).(word_value)));
                                    StorageValue_orig :=
                                      (Build_word ((block_value.(StorageBlockRow_value).(StorageValue_curr)).(word_value))) |}))
      else
        liftR ((k_aload (a))) >>= fun acc =>
        liftR ((keccak256_word (Build_word ((s))))) >>= fun slot_hash =>
        let value :=
          if acc.(Account_storage_cleared) then (ZERO_WORD).(word_value)
          else
            (stateless_storage_by_key (acc.(Account_info).(AccountInfo_storage_root)) (slot_hash)).(word_value) in
        liftR ((storage_block_cache (key) (slot_hash) (Build_word ((value))))) >>
        returnR (StorageValue) (({| StorageValue_curr := (Build_word (value));
                                    StorageValue_orig := (Build_word (value)) |})))
      : MR (StorageValue) (StorageValue)).

Definition k_sstore (a : vec (mword 8) 20) (s : word) (v : StorageValue)
(*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let s := (s).(word_value) in
   let key := storage_key (a) (Build_word ((s))) in
   (storage_tx_update (({| StorageEntry_key := key;  StorageEntry_value := v |})))
    : M (unit).

Definition k_tload (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (word) :=
   let s := (s).(word_value) in
   (((transient_load (a) (Build_word ((s)))) >>= fun semanticResult =>
     returnM (semanticResult).(word_value))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition k_tstore (a : vec (mword 8) 20) (s : word) (v : word)
(*(0 <=? s) && (s <=? (2 ^ 256 - 1))*) (*(0 <=? v) && (v <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let s := (s).(word_value) in
   let v := (v).(word_value) in
   (transient_store (a) (Build_word ((s))) (Build_word ((v))))
    : M (unit).

Definition k_log_topics (topics : LogTopics) : M (unit) :=
   match topics with
   | LogTopics0 tt => returnM (tt)
   | LogTopics1 t0 => let t0 := (t0).(word_value) in (log_add_topic (Build_word ((t0))))  : M (unit)
   | LogTopics2 (t0, t1) =>
      let t0 := (t0).(word_value) in
      let t1 := (t1).(word_value) in
      (log_add_topic (Build_word ((t0)))) >> (log_add_topic (Build_word ((t1))))  : M (unit)
   | LogTopics3 (t0, t1, t2) =>
      let t0 := (t0).(word_value) in
      let t1 := (t1).(word_value) in
      let t2 := (t2).(word_value) in
      (log_add_topic (Build_word ((t0)))) >>
      (log_add_topic (Build_word ((t1)))) >> (log_add_topic (Build_word ((t2))))  : M (unit)
   | LogTopics4 (t0, t1, t2, t3) =>
      let t0 := (t0).(word_value) in
      let t1 := (t1).(word_value) in
      let t2 := (t2).(word_value) in
      let t3 := (t3).(word_value) in
      (log_add_topic (Build_word ((t0)))) >>
      (log_add_topic (Build_word ((t1)))) >>
      (log_add_topic (Build_word ((t2)))) >> (log_add_topic (Build_word ((t3))))  : M (unit)
   end
    : M (unit).

Definition k_log_data (data : LogData) : M (unit) :=
   match data with
   | LogDataMemory (@existT _ _ len (@existT _ _ off bytes)) =>
