    : M (bool).

Definition k_transfer (src : vec (mword 8) 20) (dst : vec (mword 8) 20) (v : word)
(*(0 <=? v) && (v <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let v := (v).(word_value) in
   (k_aload (src)) >>= fun src_acc =>
   (k_aload (dst)) >>= fun dst_acc =>
   let value_is_zero := word_is_zero (v) in
   (if orb (value_is_zero) ((generic_eq (src) (dst))) then returnM (tt)
    else
      let source_balance :=
        (alu_sub (Build_word (((src_acc.(Account_info).(AccountInfo_balance)).(word_value))))
           (Build_word ((v)))).(word_value) in
      (store_account_info (src) (src_acc)
         ({[ src_acc.(Account_info) with AccountInfo_balance := (Build_word (source_balance)) ]})) >>
      let destination_balance :=
        (alu_add (Build_word (((dst_acc.(Account_info).(AccountInfo_balance)).(word_value)))) (v)).(word_value) in
      (store_account_info (dst) (dst_acc)
         ({[ dst_acc.(Account_info) with AccountInfo_balance := (Build_word (destination_balance)) ]})) >>
      (k_emit_transfer_log (src) (dst) (Build_word ((v))))
       : M (unit))
    : M (unit).

